export const w2RegionAt = (x, y) => {
  let best = "crossing", d = 1e9;
  for (const [k, r] of Object.entries(W2_REGIONS)) {
    const q = ((x - r[3]) / r[5]) ** 2 + ((y - r[4]) / r[6]) ** 2;
    if (q < d) { d = q; best = k; }
  }
  return best;
};

